    'course.expand': 'Näytä kurssi',
    'course.open': 'Avaa peruskurssi',
    'course.open.hint': 'Vuorovaikutteinen läpikäynti kaikista tiloista esimerkkidatalla',
    'course.offer': 'Uutta: peruskurssi esittelee koko sovelluksen vaihe vaiheelta esimerkkidatan avulla.',
    'course.process.column': 'tuhansina',
    'course.viz.chart': 'Väkiluku lääneittäin 2024',
    'course.welcome.title': 'Tervetuloa Dataspatiumiin',
    'course.welcome.p1': 'Dataspatium noutaa, muokkaa, analysoi, visualisoi ja vie dataa kokonaan selaimessa. Mitään ei asenneta, eikä datasi poistu tietokoneelta, ellet itse nouda sitä rajapinnasta.',
    'course.welcome.p2': 'Peruskurssi kestää noin kymmenen minuuttia. Seuraat konkreettista esimerkkiä, {example}, sovelluksen kahdeksan tilan läpi: {modes}. Jokaisessa vaiheessa voit tehdä tehtävän itse tai antaa kurssin tehdä sen puolestasi.',
    'course.welcome.p3': 'Näkymä on sama kaikissa tiloissa: tilat ylhäällä, kohdepaneeli vasemmalla, työalue keskellä, ominaisuudet oikealla ja loki alhaalla. Kurssin voi pienentää ja avata uudelleen ohjeesta.',
    'course.import.title': 'Nouda: hae dataa',
    'course.import.p1': 'Kaikki sovelluksen data on aineistoissa: taulukoissa, joissa on nimetyt sarakkeet ja jokaisella sarakkeella tyyppi, kuten teksti, kokonaisluku, luku tai päivämäärä. Dataa voi noutaa tiedostoista (CSV, Excel, JSON, Parquet, SPSS ja muut), liitetystä tekstistä, verkko-osoitteista ja viranomaisten avoimista rajapinnoista kaikkialta Pohjoismaista.',
    'course.import.task': 'Siirry tilaan {mode} ja napsauta {button}. Näin syntyy aineisto {name}.',
    'course.import.done': 'Aineisto on luotu: 290 Ruotsin kuntaa, sarakkeina kommunkod (kuntakoodi), kommun (kunta), lanskod (läänikoodi), lan (lääni), ar (vuosi) ja folkmangd (väkiluku). Lyhyt nimi on {short}.',
    'course.manage.title': 'Hallitse: aineistot ja työtila',
    'course.manage.p1': 'Jokaisella aineistolla on nimi ja lyhyt nimi. Lyhyessä nimessä, tässä {short}, on vain pieniä kirjaimia, numeroita ja alaviivoja, ja sitä käytetään SQL:ssä ja R:ssä. Tilassa {mode} näet lähteen, koon, sarakkeet tyyppeineen ja kuvauksineen sekä versiot, joihin voit palata.',
    'course.manage.p2': 'Kaikki tallentuu automaattisesti selaimeen. Varmuuskopioi työtila silloin tällöin toiminnolla {backup}, jotta mitään ei katoa, jos selaimen tiedot tyhjennetään.',
    'course.manage.task': 'Avaa {mode}, valitse aineisto kohdepaneelista ja katso sen tiedot ja sarakkeet.',
    'course.manage.done': 'Täällä voit myös vaihtaa nimen ja lyhyen nimen, jakaa aineistoja paketteina ja poistaa niitä.',
    'course.process.title': 'Muokkaa: siivoa ja laske',
    'course.process.p1': 'Tilassa {mode} näet koko taulukon. Napsauta sarakkeen otsikkoa lajitellaksesi ja nähdäksesi sarakkeen profiilin: puuttuvat arvot, yksilölliset arvot ja jakauman. Korjaa arvoja suoraan soluissa tai toiminnoilla.',
    'course.process.p2': 'Jokaisesta muutoksesta tulee vaihe aineiston kohtaan {recipe}. Vaiheet voi perua, ajaa uudelleen datan uudelle versiolle ja kopioida R- tai SQL-koodina.',
    'course.process.task': 'Tee sarake, jossa väkiluku on tuhansina: {mode} → {actions} → {group} → {op}. Anna nimeksi {column} ja lausekkeeksi {expression}.',
    'course.process.done': 'Sarake {column} on nyt taulukon viimeisenä, ja vaihe näkyy reseptissä.',
    'course.sql.title': 'Analysoi: kysy SQL:llä',
    'course.sql.p1': '{mode} on koodin ja tilastojen tila. SQL-välilehdellä valitun aineiston nimi on {data}, mutta kaikkiin aineistoihin pääsee käsiksi myös niiden lyhyillä nimillä. Siksi yksi kysely voi yhdistää useita aineistoja.',
    'course.sql.task': 'Avaa {mode} → {tab}, kirjoita alla oleva kysely ja napsauta {run}. Kysely laskee väkiluvun yhteen lääneittäin.',
    'course.sql.done': 'Tukholman lääni on suurin, lähes 2,5 miljoonaa asukasta, ja seuraavina tulevat Länsi-Götanmaan ja Skånen läänit. Painikkeella {save} tuloksesta tulee uusi aineisto.',
    'course.r.title': 'Analysoi: laske R:llä',
    'course.r.p1': 'R-välilehti ajaa R:ää suoraan selaimessa, mukana paketit kuten dplyr ja ggplot2. {read} lukee aineiston data framena, ja {write} tallentaa data framen uutena aineistona. Ensimmäisellä kerralla R:n käynnistyminen kestää muutaman sekunnin.',
    'course.r.task': 'Avaa {mode} → {tab}, kirjoita alla oleva koodi ja napsauta {run}. Koodi tiivistää väkiluvun ja piirtää histogrammin.',
    'course.r.done': 'Mediaani on hieman yli 16 000 asukasta: puolet kunnista on sitä pienempiä, ja suurimmassa, Tukholmassa, on lähes miljoona asukasta. Siksi kaaviossa on logaritminen asteikko.',
    'course.viz.title': 'Visualisoi: tee kaavio',
    'course.viz.p1': 'Kaaviot tehdään kaavionrakentimella (Vega-Lite), valmiilla D3-malleilla tai R:llä. Kaikki käyttävät sovelluksen värejä ja kirjasimia, piirtyvät uudelleen datan muuttuessa ja voidaan koota kojelaudoiksi yhteisin suodattimin.',
    'course.viz.task': 'Avaa {mode} → {new} → {builder}. Valitse {type}, aseta {x} arvoon lan ({y} on jo folkmangd) ja napsauta {save}.',
    'course.viz.done': 'Kaavio on tallennettu. Kokeile myös kaaviotyyppiä {map} yhdessä esimerkkiaineiston {boundaries} kanssa, niin näet väkiluvun kartalla.',
    'course.export.title': 'Vie: jaa tulos',
    'course.export.p1': 'Tilassa {mode} tallennat datan CSV-, Excel-, JSON-, Parquet-, SQLite-, SPSS- ja muissa muodoissa, kaaviot PNG-, SVG-, PDF- tai PowerPoint-muodossa ja asiakirjat malleista Word-, PDF-, HTML- tai LaTeX-muodossa, myös yhden asiakirjan ryhmää kohden yhdellä ajolla.',
    'course.export.task': 'Avaa {mode}, valitse esimerkiksi Excel-muoto ja napsauta {run}.',
    'course.export.done': 'Tiedosto päätyy selaimen ladattuihin tiedostoihin. Välilehdet {charts} ja {documents} toimivat samalla tavalla kaavioille ja asiakirjoille.',
    'course.finish.title': 'Valmis: näin jatkat',
    'course.finish.p1': 'Olet käynyt läpi koko ketjun: noutamisen, hallinnan, muokkauksen, analyysin, visualisoinnin ja viennin.',
    'course.finish.p2': 'Jatka omalla datallasi: pudota tiedosto tilaan {import}, valitse maat ja nouda avoimesta rajapinnasta, kirjoita muistikirjoja tekstillä, R:llä ja SQL:llä tilassa {analyse} tai tee asiakirjamalleja tilassa {export}. Alt+1–6 vaihtaa tilaa, ja {palette} avaa komentopaletin.',
    'course.finish.p3': 'Kurssi on edelleen saatavilla kohdassa {help} ja komentopaletissa.',
    'floating.collapse': 'Pienennä',
