    'families.sheets.sheet': 'Laskentataulukko',
    'families.postgrest.desc': 'PostgreSQL:n taulut ja näkymät PostgRESTin tai Supabasen kautta. Jokaisesta taulusta tulee päätepiste, jossa on sarakevalinta, lajittelu ja suodatin.',
    'families.postgrest.cors': 'PostgREST ja Supabase sallivat selainkutsut oletuksena.',
    'families.odata.desc': 'OData v4 -palvelut (Dynamics, SharePoint, SAP, tilastopalvelut). Entiteettijoukoista tulee päätepisteitä, joissa on $select, $filter ja $orderby; lisäsivut seurataan @odata.nextLink-linkistä.',
    'families.odata.cors': 'Riippuu palvelusta; palvelimen on sallittava selaimen alkuperä (kansiosta avattu sivu lähettää alkuperän "null").',
    'families.graphql.desc': 'Mikä tahansa GraphQL-päätepiste. Kirjoitat kyselyn itse; vastauksen ensimmäisestä listasta tulee taulukko.',
    'families.graphql.cors': 'Riippuu palvelimesta; useimmat GraphQL-palvelimet voivat ottaa CORSin käyttöön.',
    'families.couchdb.desc': 'CouchDB:n tietokannat. Tietokannan kaikista dokumenteista tulee rivejä ja kentistä sarakkeita.',
    'families.couchdb.cors': 'Ota CORS käyttöön CouchDB:ssä (Configuration → CORS tai [cors] local.ini-tiedostossa) ja lisää alkuperä.',
    'families.clickhouse.desc': 'ClickHouse HTTP-rajapinnan kautta. Jokainen taulu saa SQL-päätepisteen, jota voit muokata vapaasti.',
    'families.clickhouse.cors': 'Sovellus lähettää add_http_cors_header=1, joten ClickHouse vastaa CORS-otsakkeilla, kun käyttäjä saa muuttaa asetusta.',
    'families.elasticsearch.desc': 'Elasticsearchin tai OpenSearchin indeksit. Osumien _source muuttuu sarakkeiksi; enintään 10 000 riviä hakua kohden.',
    'families.elasticsearch.cors': 'Aseta http.cors.enabled: true ja http.cors.allow-origin tiedostossa elasticsearch.yml (samat avaimet OpenSearchissa).',
    'families.sparql.desc': 'SPARQL-päätepisteet kuten Wikidata, Europeana tai oma triple store. Kyselyn muuttujista tulee sarakkeita.',
    'families.sparql.cors': 'Julkiset päätepisteet kuten Wikidata sallivat selainkutsut; omat palvelimet (Fuseki, GraphDB, Virtuoso) voivat ottaa CORSin käyttöön.',
    'families.influxdb.desc': 'InfluxDB v2 Flux-kyselyillä. Vastauksesta (annotoitu CSV) tulee taulukko, jossa ovat _time, _value, _field ja tagit.',
    'families.influxdb.cors': 'Palvelimen on vastattava CORS-otsakkeilla; jos se ei onnistu selaimesta, käytä välityspalvelinasetusta tai siltaa ODBC:n kautta.',
    'families.sheets.desc': 'Google-laskentataulukko, joka on julkaistu verkossa tai jaettu linkillä. Se luetaan CSV-muodossa.',
    'families.sheets.cors': 'Taulukon on oltava julkaistu verkossa (Tiedosto → Jaa → Julkaise verkossa) tai jaettu linkillä; yksityisiä taulukoita ei voi lukea.',
    'families.airtable.desc': 'Airtable-kannan taulut henkilökohtaisella käyttöoikeustunnisteella. Tietueista tulee rivejä ja kentistä sarakkeita; kaikki sivut haetaan.',
    'families.airtable.cors': 'Airtablen API sallii selainkutsut.',
